# ----------------------------------------------------------------------------
# Small helpers
# ----------------------------------------------------------------------------
_font_cache = {}

def F(size, bold=True):
    key = (size, bold)
    if key not in _font_cache:
        _font_cache[key] = pygame.font.SysFont(
            ["segoeui", "roboto", "notosans", "dejavusans", "arial", "sans"],
            size, bold=bold)
    return _font_cache[key]

def clean(s):
    """Drop glyphs most fonts cannot show (emoji etc.), keep the rest."""
    out = []
    for ch in str(s):
        o = ord(ch)
        if o < 0x2500 or 0x2600 <= o <= 0x27BF or 0x3000 <= o <= 0x30FF \
                or 0x0980 <= o <= 0x09FF or 0x4E00 <= o <= 0x9FFF:
            out.append(ch)
    return "".join(out).strip()

def text(surf, s, cx, y, size, color=INK, bold=True, align="center"):
    img = F(size, bold).render(clean(s), True, color)
    x = cx - img.get_width() // 2 if align == "center" else cx
    surf.blit(img, (x, y))
    return img.get_width()

def text_left(surf, s, x, y, size, color=INK, bold=True):
    img = F(size, bold).render(clean(s), True, color)
    surf.blit(img, (x, y))
    return img.get_width()

def rrect(surf, rect, color, radius=10, width=0):
    pygame.draw.rect(surf, color, rect, width, border_radius=radius)

def thick_line(surf, color, p1, p2, w):
    pygame.draw.line(surf, color, p1, p2, w)
    r = max(1, w // 2)
    pygame.draw.circle(surf, color, (int(p1[0]), int(p1[1])), r)
    pygame.draw.circle(surf, color, (int(p2[0]), int(p2[1])), r)

def quad_points(p0, p1, p2, n=10):
    pts = []
    for i in range(n + 1):
        t = i / n
        x = (1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t ** 2 * p2[0]
        y = (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t ** 2 * p2[1]
        pts.append((x, y))
    return pts

def img_from_b64(b64):
    try:
        return pygame.image.load(io.BytesIO(base64.b64decode(b64))).convert_alpha()
    except Exception:
        return None

def snd_from_b64(b64):
    try:
        return pygame.mixer.Sound(io.BytesIO(base64.b64decode(b64)))
    except Exception:
        return None

class Anim:
    """A horizontal sprite sheet with per-frame durations."""
    def __init__(self, meta):
        self.ok = False
        if not meta:
            return
        sheet = img_from_b64(meta["b64"])
        if sheet is None:
            return
        self.sheet, self.n = sheet, meta["frames"]
        self.fw, self.fh = meta["fw"], meta["fh"]
        self.durs = meta.get("durs") or [60] * self.n
        self.total = max(1, sum(self.durs))
        self.ok = True

    def frame(self, t_ms, w=None):
        if not self.ok:
            return None
        t = t_ms % self.total
        acc = 0
        idx = 0
        for i, d in enumerate(self.durs):
            acc += d
            if t < acc:
                idx = i
                break
        src = pygame.Rect(idx * self.fw, 0, self.fw, self.fh)
        img = self.sheet.subsurface(src)
        if w:
            h = max(1, round(self.fh * w / self.fw))
            img = pygame.transform.smoothscale(img, (w, h))
        return img

def circle_face(img, r):
    """Crop an image into a ringed circle of radius r (like the web drawFace)."""
    d = r * 2
    if img is None:
        s = pygame.Surface((d, d), pygame.SRCALPHA)
        pygame.draw.circle(s, (255, 217, 77), (r, r), r)
        pygame.draw.circle(s, (0, 0, 0), (r, r), r, 2)
        return s
    src = pygame.transform.smoothscale(img, (d, d))
    mask = pygame.Surface((d, d), pygame.SRCALPHA)
    pygame.draw.circle(mask, (255, 255, 255, 255), (r, r), r)
    src.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
    pygame.draw.circle(src, (40, 40, 40), (r, r), r, 2)
    return src

# ----------------------------------------------------------------------------
# Profile (guest id + name + best + submitted best)
# ----------------------------------------------------------------------------
def load_profile():
    p = {"uid": None, "name": "", "best": 0, "my_best": 0}
    try:
        with open(PROFILE_PATH, encoding="utf-8") as fh:
            p.update(json.load(fh))
    except Exception:
        pass
    if not p["uid"]:
        alpha = "abcdefghijklmnopqrstuvwxyz0123456789"
        p["uid"] = "".join(random.choice(alpha) for _ in range(16))
        save_profile(p)
    return p

def save_profile(p):
    try:
        with open(PROFILE_PATH, "w", encoding="utf-8") as fh:
            json.dump(p, fh)
    except Exception:
        pass

def my_key(profile):
    return "u_" + profile["uid"]

# ----------------------------------------------------------------------------
# Firebase (same public REST endpoints the web version uses)
# ----------------------------------------------------------------------------
def db_get(path):
    req = urllib.request.Request(DB_URL + path,
                                 headers={"User-Agent": "BedBouncePy/1.0"})
    with urllib.request.urlopen(req, timeout=8) as r:
        return json.loads(r.read().decode("utf-8"))

def db_put(path, data):
    body = json.dumps(data).encode("utf-8")
    req = urllib.request.Request(DB_URL + path, data=body, method="PUT",
                                 headers={"User-Agent": "BedBouncePy/1.0",
                                          "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=8) as r:
        return r.status

def giveaway_left():
    """Seconds until this week's giveaway ends (Sunday 23:59:59, Dhaka)."""
    now = time.time()
    dhaka = time.gmtime(now + 6 * 3600)          # UTC+6 wall clock
    add = (6 - dhaka.tm_wday) % 7                # days until Sunday
    end = (now + 6 * 3600) - (dhaka.tm_hour * 3600 + dhaka.tm_min * 60
                              + dhaka.tm_sec) + add * 86400 + 86399
    left = end - (now + 6 * 3600)
    if left < 0:
        left += 7 * 86400
    return int(left)

def fmt_left(sec):
    d, rem = divmod(sec, 86400)
    h, rem = divmod(rem, 3600)
    m, s = divmod(rem, 60)
    if d:
        return "%dd %02d:%02d:%02d" % (d, h, m, s)
    return "%02d:%02d:%02d" % (h, m, s)

# ----------------------------------------------------------------------------
# Game
# ----------------------------------------------------------------------------
class BedBounce:
    def __init__(self, headless=False):
        pygame.init()
        self.headless = headless
        pygame.display.set_caption("Bed Bounce — by XDOTDEX")
        info = pygame.display.Info()
        win_h = min(VH, max(560, info.current_h - 70)) if info.current_h else VH
        self.win = pygame.display.set_mode(
            (round(VW * win_h / VH), win_h), pygame.RESIZABLE)
        self.canvas = pygame.Surface((VW, VH))
        self.clock = pygame.time.Clock()
        self.profile = load_profile()
        self.best = int(self.profile.get("best") or 0)

        # ---- assets ----
        A = ASSETS
        self.anim_meteor = Anim(A.get("meteor"))
        self.anim_rocket = Anim(A.get("rocket"))
        self.anim_badges = [Anim(A.get("badge1")), Anim(A.get("badge2")),
                            Anim(A.get("badge3"))]
        self.anim_boss = Anim(A.get("badgeboss"))
        sleeper_raw = img_from_b64(A["sleeper"]["b64"]) if A.get("sleeper") else None
        self.sleeper_face = circle_face(sleeper_raw, 19)
        self.faller_faces = []
        for k in ("faller1", "faller2"):
            if A.get(k):
                self.faller_faces.append(
                    circle_face(img_from_b64(A[k]["b64"]), 24))
        if not self.faller_faces:
            self.faller_faces = [circle_face(None, 24)]
        self.custom_face = None
        self._load_custom_face()

        # sock-feet surfaces (drawn once, rotated like the web ellipses)
        self.foot1 = self._foot(14, 24, -0.45)
        self.foot2 = self._foot(12, 20, -0.85)

        # ---- audio ----
        self.music_on = True
        self._audio_ready = False
        try:
            pygame.mixer.init()
            self._audio_ready = True
        except Exception:
            pass
        self.snd_bounce = [snd_from_b64(A[k]["b64"]) for k in
                           ("bounce1", "bounce2", "bounce3") if A.get(k)]
        self.snd_splat = snd_from_b64(A["splat"]["b64"]) if A.get("splat") else None
        self.snd_over = snd_from_b64(A["gameover"]["b64"]) if A.get("gameover") else None
        if self._audio_ready and A.get("theme"):
            try:
                pygame.mixer.music.load(io.BytesIO(base64.b64decode(A["theme"]["b64"])))
                pygame.mixer.music.set_volume(0.28)
                pygame.mixer.music.play(-1)
            except Exception:
                pass

        # ---- state ----
        self.state = "menu"          # menu | playing | paused | over
        self.score = 0
        self.frame = 0
        self.bed_x = VW / 2
        self.bed_target = VW / 2
        self.bed_w = max(210, min(VW * 0.62, 330))
        self.squash = 0.0
        self.faller = None
        self.next_spawn = 0
        self.particles = []
        self.floaters = []
        self.splat_mark = None
        self.shake = 0.0
        self.flash = 0.0
        self.dragging = False
        self.drag_off = 0.0
        self.new_best = False
        self.over_at = 0
        self.over_msg = ""
        self.hint_until = 0
        self.editing_name = not bool(self.profile.get("name"))
        self.name_buf = self.profile.get("name") or ""

        # ---- leaderboard ----
        self.board_open = False
        self.board_rows = None       # None = loading / not fetched yet
        self.board_stamp = 0
        self.board_fetching = False
        self.avatars = {}            # url -> Surface | False | None(loading)
        self._fetch_board()

    # ---------- assets helpers ----------
    def _foot(self, w, h, ang):
        s = pygame.Surface((w + 4, h + 4), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (245, 242, 234), (2, 2, w, h))
        pygame.draw.ellipse(s, (120, 120, 120), (2, 2, w, h), 1)
        return pygame.transform.rotate(s, -math.degrees(ang))

    def _load_custom_face(self, path=None):
        cands = []
        if path:
            cands.append(path)
        here = os.path.dirname(os.path.abspath(__file__))
        cands.append(os.path.join(here, "myface.png"))
        for c in cands:
            try:
                if os.path.exists(c):
                    img = pygame.image.load(c).convert_alpha()
                    self.custom_face = circle_face(img, 24)
                    return
            except Exception:
                pass

    # ---------- leaderboard ----------
    def _fetch_board(self):
        if self.board_fetching:
            return
        self.board_fetching = True

        def work():
            rows = None
            try:
                data = db_get("/scores.json") or {}
                rows = []
                for key, v in data.items():
                    if isinstance(v, dict) and "score" in v:
                        rows.append({"key": key, "name": v.get("name") or "?",
                                     "score": int(v.get("score") or 0),
                                     "photo": v.get("photo")})
                rows.sort(key=lambda r: -r["score"])
                mk = my_key(self.profile)
                for r in rows:
                    if r["key"] == mk:
                        self.profile["my_best"] = max(
                            int(self.profile.get("my_best") or 0), r["score"])
            except Exception:
                rows = None
            self.board_rows = rows
            self.board_stamp = time.time()
            self.board_fetching = False
            if rows:
                for r in rows[:10]:
                    if r.get("photo"):
                        self._fetch_avatar(r["photo"])
        threading.Thread(target=work, daemon=True).start()

    def _fetch_avatar(self, url):
        if url in self.avatars:
            return
        self.avatars[url] = None

        def work():
            surf = False
            try:
                req = urllib.request.Request(
                    url, headers={"User-Agent": "BedBouncePy/1.0"})
                with urllib.request.urlopen(req, timeout=8) as r:
                    raw = r.read()
                img = pygame.image.load(io.BytesIO(raw)).convert_alpha()
                surf = circle_face(img, 15)
            except Exception:
                surf = False
            self.avatars[url] = surf
        threading.Thread(target=work, daemon=True).start()

    def _submit_score(self):
        if self.score <= 0:
            return
        if self.score <= int(self.profile.get("my_best") or 0):
            return
        rec = {"name": self.profile.get("name") or "Player",
               "score": self.score, "ts": int(time.time() * 1000)}
        key = my_key(self.profile)

        def work():
            try:
                db_put("/scores/%s.json" % key, rec)
                self.profile["my_best"] = self.score
                save_profile(self.profile)
                self.board_rows = None
                self._fetch_board()
            except Exception:
                pass
        threading.Thread(target=work, daemon=True).start()

    # ---------- game flow ----------
    def start_game(self):
        self.score = 0
        self.particles, self.floaters = [], []
        self.splat_mark = None
        self.shake = self.flash = 0.0
        self.bed_x = self.bed_target = VW / 2
        self.squash = 0.0
        self.new_best = False
        self.faller = None
        self._spawn()
        self.state = "playing"
        self.hint_until = time.time() + 2.6

    def _spawn(self):
        self.faller = {
            "x": 50 + random.random() * (VW - 100),
            "y": -50.0, "vy": 0.0,
            "vx": (random.random() - 0.5) * 0.6,
            "rot": 0.0, "phase": random.random() * math.pi * 2,
            "face": self.custom_face or random.choice(self.faller_faces),
            "state": "falling", "splat_t": 0.0, "r": 24,
        }

    def _bounce(self):
        f = self.faller
        bed_left = self.bed_x - self.bed_w / 2
        head = 2 <= (f["x"] - bed_left) <= 70
        pts = 2 if head else 1
        self.score += pts
        if self.score > self.best:
            self.best = self.score
            if self.score > 1:
                self.new_best = True
        self.floaters.append({"x": f["x"], "y": BED_TOP - 34,
                              "text": "+%d%s" % (pts, " HEAD!" if head else ""),
                              "life": 1.0, "gold": head})
        for _ in range(10):
            self.particles.append({
                "x": f["x"], "y": BED_TOP - 4,
                "vx": (random.random() - 0.5) * 4,
                "vy": -random.random() * 3.4 - 0.6,
                "life": 1.0, "s": random.random() * 3 + 2, "c": GOLD})
        self.squash = 1.0
        snd = random.choice(self.snd_bounce) if self.snd_bounce else None
        if snd:
            try:
                snd.play()
            except Exception:
                pass
        self.faller = None
        self.next_spawn = time.time() * 1000 + 420 + random.random() * 380

    def _game_over(self):
        self.state = "over"
        self.over_at = time.time()
        self.over_msg = ("New best score!" if self.new_best
                         else random.choice(OVER_MSGS))
        if self.new_best:
            self.profile["best"] = self.best
            save_profile(self.profile)
        if self.snd_splat:
            try:
                self.snd_splat.play()
            except Exception:
                pass
        if self.snd_over:
            try:
                pygame.time.set_timer(pygame.USEREVENT + 7, 260, loops=1)
            except Exception:
                pass
        self._submit_score()

    # ---------- physics / update ----------
    def update(self, dt):
        self.frame += 1
        # bed easing toward target (same 0.42 factor as the web version)
        self.bed_x += (self.bed_target - self.bed_x) * min(1, 0.42 * dt)
        self.bed_x = max(self.bed_w / 2, min(VW - self.bed_w / 2, self.bed_x))
        if self.squash > 0:
            self.squash = max(0.0, self.squash - 0.09 * dt)
        if self.flash > 0:
            self.flash = max(0.0, self.flash - 0.03 * dt)
        if self.shake > 0:
            self.shake *= 0.86 ** dt
            if self.shake < 0.3:
                self.shake = 0.0

        if self.state == "playing":
            keys = pygame.key.get_pressed()
            spd = 7 * dt
            if keys[pygame.K_LEFT]:
                self.bed_target = max(self.bed_w / 2, self.bed_target - spd)
            if keys[pygame.K_RIGHT]:
                self.bed_target = min(VW - self.bed_w / 2, self.bed_target + spd)
            if self.faller is None and time.time() * 1000 >= self.next_spawn:
                self._spawn()

        f = self.faller
        if f is not None:
            if f["state"] == "falling":
                grav = 0.34 + min(self.score * 0.012, 0.22)
                f["vy"] += grav * dt
                f["y"] += f["vy"] * dt
                f["x"] += f["vx"] * dt + math.sin(self.frame / 26 + f["phase"]) * 0.35 * dt
                f["rot"] = math.sin(self.frame / 20 + f["phase"]) * 0.14
                if f["x"] < 30:
                    f["x"], f["vx"] = 30, abs(f["vx"])
                if f["x"] > VW - 30:
                    f["x"], f["vx"] = VW - 30, -abs(f["vx"])
                feet = f["y"] + f["r"] * 0.85 + 26 + 24
                over_bed = (self.bed_x - self.bed_w / 2 + 14 < f["x"]
                            < self.bed_x + self.bed_w / 2 - 6)
                if (self.state == "playing" and f["vy"] > 0 and over_bed
                        and BED_TOP + 4 <= feet <= BED_TOP + 34):
                    f["y"] -= feet - (BED_TOP + 4)
                    self._bounce()
                elif feet >= FLOOR_Y + 8:
                    self.splat_mark = f["x"]
                    self.shake, self.flash = 13.0, 1.0
                    f["state"], f["splat_t"] = "splat", 0.0
                    f["y"] = FLOOR_Y + 8 - 62
                    for i in range(16):
                        self.particles.append({
                            "x": f["x"], "y": FLOOR_Y + 6,
                            "vx": (random.random() - 0.5) * 6,
                            "vy": -random.random() * 4 - 0.5,
                            "life": 1.0, "s": random.random() * 3.4 + 2,
                            "c": GREEN if i % 2 else (232, 168, 18)})
                    if self.state == "playing":
                        self._game_over()
            elif f["state"] == "splat":
                f["splat_t"] += dt
                if f["splat_t"] > 40:
                    self.faller = None

        for p in self.particles:
            p["x"] += p["vx"] * dt
            p["y"] += p["vy"] * dt
            p["vy"] += 0.12 * dt
            p["life"] -= 0.03 * dt
        self.particles = [p for p in self.particles if p["life"] > 0]
        for ft in self.floaters:
            ft["y"] -= 0.9 * dt
            ft["life"] -= 0.022 * dt
        self.floaters = [t for t in self.floaters if t["life"] > 0]

    # ---------- drawing: scene ----------
    def draw_scene(self, now_ms):
        c = self.canvas
        c.fill(CREAM)
        if self.flash > 0:
            ov = pygame.Surface((VW, VH), pygame.SRCALPHA)
            ov.fill((220, 60, 40, int(self.flash * 0.13 * 255)))
            c.blit(ov, (0, 0))
        # meteors in the sky (same loops as the web CSS)
        self._meteor(now_ms, 0.10 * VW, 0.05 * VH, 64, 8000, 0)
        self._meteor(now_ms, 0.56 * VW, 0.01 * VH, 46, 11000, 2500)
        self._meteor(now_ms, 0.84 * VW, 0.09 * VH, 54, 9500, 5200)
        # rocket, bobbing in the centre of the sky
        rk = self.anim_rocket.frame(now_ms)
        if rk is not None:
            bob = math.sin(now_ms / 3600 * math.pi) * -9
            c.blit(rk, (VW // 2 - rk.get_width() // 2, int(118 + bob)))
        # quote (two centred lines, gentle pulse like the web version)
        a = 0.72 + 0.28 * math.sin(now_ms / 1400)
        qcol = tuple(int(90 + (43 - 90) * a) for _ in range(3))
        text(c, "No awakening here. Only sleep that", VW // 2, 258, 15, qcol, bold=False)
        text(c, "never ends, among dead stars", VW // 2, 278, 15, qcol, bold=False)
        # floor
        pygame.draw.rect(c, (227, 218, 198), (0, FLOOR_Y, VW, VH - FLOOR_Y))
        pygame.draw.rect(c, (203, 191, 163), (0, FLOOR_Y, VW, 3))
        for fy in range(FLOOR_Y + 14, VH, 16):
            pygame.draw.line(c, (214, 203, 175), (0, fy), (VW, fy))
        # splat mark
        if self.splat_mark is not None:
            pygame.draw.ellipse(c, (40, 40, 40),
                                (self.splat_mark - 30, FLOOR_Y + 9, 60, 14))
        # dashed guide line under the falling figure
        f = self.faller
        if (f is not None and f["state"] == "falling"
                and self.state == "playing"):
            gy = f["y"] + f["r"] + 52
            y = gy
            while y < BED_TOP:
                pygame.draw.line(c, (168, 164, 154), (f["x"], y),
                                 (f["x"], min(y + 7, BED_TOP)), 2)
                y += 15
        # the bed + sleeper
        self.draw_bed()
        # the faller
        if f is not None:
            if f["state"] == "splat":
                self._draw_splat(f)
            else:
                self.draw_stick(c, f, 0, 0)
        # particles
        for p in self.particles:
            s = pygame.Surface((int(p["s"] * 2 + 2), int(p["s"] * 2 + 2)),
                               pygame.SRCALPHA)
            col = p["c"] + (int(255 * max(0.0, p["life"])),)
            pygame.draw.circle(s, col, (s.get_width() // 2, s.get_height() // 2),
                               max(1, int(p["s"])))
            c.blit(s, (p["x"] - s.get_width() / 2, p["y"] - s.get_height() / 2))
        # floating score text
        for ft in self.floaters:
            col = GOLD_D if ft["gold"] else (68, 68, 68)
            img = F(21).render(ft["text"], True, col)
            img.set_alpha(int(255 * max(0.0, ft["life"])))
            c.blit(img, (ft["x"] - img.get_width() / 2, ft["y"] - 10))
        # GitHub credit, bottom-left
        text_left(c, "github.com/XDOTDEX", 10, VH - 24, 12, MUTED, bold=False)

    def _meteor(self, now_ms, x, y, size, dur, delay):
        t = (now_ms - delay) % dur
        frac = t / dur
        if frac > 0.58:
            return
        img = self.anim_meteor.frame(now_ms, size)
        if img is None:
            return
        dx, dy = -48 * (frac / 0.58), 124 * (frac / 0.58)
        alpha = 255
        if frac < 0.10:
            alpha = int(255 * frac / 0.10)
        elif frac > 0.48:
            alpha = int(255 * (0.58 - frac) / 0.10)
        img = img.copy()
        img.set_alpha(alpha)
        self.canvas.blit(img, (x + dx, y + dy))

    def draw_bed(self):
        c = self.canvas
        w = self.bed_w
        left = self.bed_x - w / 2
        top = BED_TOP
        mh = 30 + self.squash * 10
        # legs
        pygame.draw.rect(c, (58, 44, 32), (left + 10, top + mh + 16, 9, 16))
        pygame.draw.rect(c, (58, 44, 32), (left + w - 19, top + mh + 16, 9, 16))
        # headboard
        rrect(c, (left - 6, top - 56, 30, mh + 34), (138, 90, 51), 6)
        rrect(c, (left - 1, top - 50, 20, mh + 22), (160, 106, 58), 4)
        rrect(c, (left - 6, top - 56, 30, mh + 34), (90, 60, 30), 6, width=2)
        # frame + mattress
        rrect(c, (left, top + mh - 2, w, 18), (110, 110, 110), 3)
        rrect(c, (left, top, w, mh), (233, 228, 214), 6)
        rrect(c, (left, top, w, mh), (120, 115, 100), 6, width=2)
        # body-shaped blanket
        bx, bw = left + 58, w - 58 - 2
        by, bh = top + 3, mh + 8
        pts = [(bx, by + bh), (bx, by + 10)]
        pts += quad_points((bx, by + 10), (bx + 2, by + 1), (bx + 16, by + 1))
        pts += quad_points((bx + 16, by + 1), (bx + bw * 0.30, by - 3),
                           (bx + bw * 0.44, by + 4))
        pts += quad_points((bx + bw * 0.44, by + 4), (bx + bw * 0.58, by + 8),
                           (bx + bw * 0.72, by + 7))
        pts += quad_points((bx + bw * 0.72, by + 7), (bx + bw * 0.90, by + 6),
                           (bx + bw - 22, by + 9))
        pts += [(bx + bw - 22, by + bh)]
        pygame.draw.polygon(c, (30, 77, 58), pts)
        pygame.draw.polygon(c, (18, 48, 36), pts, 1)
        # fold highlight
        hl = quad_points((bx + 10, by + 9), (bx + bw * 0.30, by + 4),
                         (bx + bw * 0.44, by + 10))
        hl += quad_points((bx + bw * 0.44, by + 10), (bx + bw * 0.58, by + 14),
                          (bx + bw * 0.72, by + 13))
        for i in range(len(hl) - 1):
            thick_line(c, (43, 94, 70), hl[i], hl[i + 1], 3)
        # pajama shoulder + arm resting on top
        pygame.draw.ellipse(c, (122, 162, 247), (bx - 9, by + 1, 26, 16))
        arm = quad_points((bx + 14, by + 9), (bx + bw * 0.22, by + 17),
                          (bx + bw * 0.36, by + 16), 12)
        for i in range(len(arm) - 1):
            thick_line(c, (122, 162, 247), arm[i], arm[i + 1], 9)
        pygame.draw.circle(c, (242, 194, 155),
                           (int(bx + bw * 0.385), int(by + 16)), 6)
        # pillow + sleeper face
        rrect(c, (left + 8, top - 12, 56, 26), WHITE, 9)
        rrect(c, (left + 8, top - 12, 56, 26), (150, 145, 130), 9, width=1)
        c.blit(self.sleeper_face, (left + 36 - 19, top + 1 - 19))
        # sock feet at the right end
        c.blit(self.foot1, (left + w - 13 - self.foot1.get_width() / 2,
                            top + 4 - self.foot1.get_height() / 2))
        c.blit(self.foot2, (left + w - 27 - self.foot2.get_width() / 2,
                            top + 9 - self.foot2.get_height() / 2))

    def draw_stick(self, surf, f, ox, oy):
        t = pygame.time.get_ticks() / 90 + f["phase"] * 10
        flail = 1.0 if f["state"] == "falling" else 0.4
        a1, a2 = math.sin(t) * 0.7 * flail, math.cos(t * 1.13) * 0.7 * flail
        l1, l2 = math.sin(t * 1.31) * 0.8 * flail, math.cos(t * 0.91) * 0.8 * flail
        fx, fy = f["x"] + ox, f["y"] + oy
        neck_y, hip_y = fy + f["r"] * 0.85, fy + f["r"] * 0.85 + 26
        ax1, ay1 = fx + math.cos(a1) * 24, neck_y + 5 + math.sin(a1) * 24
        ax2, ay2 = fx - math.cos(a2) * 24, neck_y + 5 + math.sin(a2) * 24
        lx1, ly1 = fx + math.sin(l1) * 22, hip_y + 24
        lx2, ly2 = fx - math.sin(l2) * 22, hip_y + 24
        pants, skin, shoe = (43, 58, 85), (242, 194, 155), (25, 25, 25)
        thick_line(surf, pants, (fx, hip_y), (lx1, ly1), 8)
        thick_line(surf, pants, (fx, hip_y), (lx2, ly2), 8)
        pygame.draw.circle(surf, shoe, (int(lx1), int(ly1)), 5)
        pygame.draw.circle(surf, shoe, (int(lx2), int(ly2)), 5)
        thick_line(surf, GREEN, (fx, neck_y + 2), (fx, hip_y), 15)
        thick_line(surf, GREEN, (fx, neck_y + 5), (ax1, ay1), 7)
        thick_line(surf, GREEN, (fx, neck_y + 5), (ax2, ay2), 7)
        pygame.draw.circle(surf, skin, (int(ax1), int(ay1)), 4)
        pygame.draw.circle(surf, skin, (int(ax2), int(ay2)), 4)
        face = pygame.transform.rotate(f["face"], -math.degrees(f["rot"]))
        surf.blit(face, (fx - face.get_width() / 2, fy - face.get_height() / 2))

    def _draw_splat(self, f):
        sp = min(f["splat_t"] / 16, 1.0)
        tmp = pygame.Surface((200, 200), pygame.SRCALPHA)
        lf = dict(f)
        lf["x"], lf["y"] = 100, FLOOR_Y + 8 - 62 - (FLOOR_Y + 8) + 128
        self.draw_stick(tmp, lf, 0, 0)
        sw = int(200 * (1 + 0.9 * sp))
        sh = max(4, int(200 * max(0.18, 1 - 0.82 * sp)))
        img = pygame.transform.scale(tmp, (sw, sh))
        self.canvas.blit(img, (f["x"] - sw / 2, FLOOR_Y + 8 - sh))

